WITH r AS (SELECT * FROM bestiary_mobs FINAL WHERE zone_id = {zone:Int64} AND mob_name = {name:String} AND capture_id NOT IN (SELECT capture_id FROM capture_trust FINAL WHERE trust = 'flagged')), m AS (SELECT model, countIfMerge(fights) AS n_fights, countIfMerge(defeated) AS n_defeated, uniqExact(capture_id) AS n_captures, sumIfMerge(delay_n) AS d_n, quantilesExactWeightedInterpolatedArrayIfMerge(0.25, 0.5, 0.75)(delay_q) AS d_q, sumMapIfMerge(delay_bins) AS d_bins, sumIfMerge(skill_delay_n) AS sd_n, quantilesExactWeightedInterpolatedArrayIfMerge(0.25, 0.5, 0.75)(skill_delay_q) AS sd_q, sumMapIfMerge(skill_delay_bins) AS sd_bins, sumMapIfMerge(gain_bins) AS g_bins, sumMapIfMerge(gain_hist) AS g_hist, sumIfMerge(round_n) AS r_n, sumIfMerge(off_hands) AS r_off, sumIfMerge(kick_n) AS r_kicks, sumMapIfMerge(main_hands) AS r_main, sumMapIfMerge(hands_after_hit) AS r_hit, sumMapIfMerge(hands_after_miss) AS r_miss, sumMapIfMerge(moves) AS t_counts, maxMapIfMerge(move_targets) AS t_targets, maxMapIfMerge(move_reach) AS t_reach, sumMapIfMerge(move_reaches) AS t_reaches, maxMapIfMerge(move_spread) AS t_spread, maxMapIfMerge(move_kb) AS t_kb, sumMapIfMerge(move_shadows) AS t_shadows, sumMapIfMerge(move_distances) AS t_dist, sumMapIfMerge(move_through) AS t_through, sumMapIfMerge(move_ready) AS t_ready, sumMapIfMerge(move_ready_coarse) AS t_ready_coarse, sumMapIfMerge(casts) AS c_casts, sumMapIfMerge(idle_casts) AS c_idle, sumMapIfMerge(cast_ready) AS c_ready, minMapIfMerge(recast) AS c_recast, sumMapIfMerge(recast_n) AS c_recast_n, sumMapIfMerge(results) AS s_results, countIfMerge(hp_n) AS h_n, sumMapIfMerge(hp_levels) AS h_levels, sumMapIfMerge(hp_level_lo) AS h_level_lo, sumMapIfMerge(hp_level_hi) AS h_level_hi, sumMapIfMerge(slot_counts) AS sl_counts, minMapIfMerge(slot_lo) AS sl_lo, maxMapIfMerge(slot_hi) AS sl_hi, minMapIfMerge(respawn_least) AS sl_least, sumMapIfMerge(th_kills) AS dr_kills, sumMapIfMerge(th_items) AS dr_items, sumMapIfMerge(th_held) AS dr_held, sumMapIfMerge(th_blind) AS dr_blind, sumMapIfMerge(sc_tiers) AS sc_t, minMapIfMerge(sc_lo) AS sc_l, maxMapIfMerge(sc_hi) AS sc_h FROM r GROUP BY model HAVING n_fights > 0), l AS (SELECT * FROM bestiary_fights WHERE zone_id = {zone:Int64} AND mob_name = {name:String} AND capture_id NOT IN (SELECT capture_id FROM capture_trust FINAL WHERE trust = 'flagged') ORDER BY ts_ms DESC LIMIT 200), kc AS (SELECT fight_key AS k_key, min(capture_id) AS k_owner, arraySort(groupUniqArray(capture_id)) AS k_copies FROM bestiary_fights WHERE zone_id = {zone:Int64} AND mob_name = {name:String} AND capture_id NOT IN (SELECT capture_id FROM capture_trust FINAL WHERE trust = 'flagged') AND fight_key IN (SELECT fight_key FROM l) GROUP BY fight_key), dh AS (SELECT model, arrayMap(t -> t.2, arraySort(t -> t.1, groupArray((b, tuple(b AS b, n AS n))))) AS l FROM (SELECT model, b, n FROM m ARRAY JOIN d_bins.1 AS b, d_bins.2 AS n) GROUP BY model), dy AS (SELECT m.model AS model, tuple(m.d_n AS n, m.d_q[2] AS median, m.d_q[1] AS p25, m.d_q[3] AS p75, dh.l AS hist) AS v FROM m LEFT JOIN dh ON dh.model = m.model WHERE m.d_n > 0), sdh AS (SELECT model, arrayMap(t -> t.2, arraySort(t -> t.1, groupArray((b, tuple(b AS b, n AS n))))) AS l FROM (SELECT model, b, n FROM m ARRAY JOIN sd_bins.1 AS b, sd_bins.2 AS n) GROUP BY model), sdy AS (SELECT m.model AS model, tuple(m.sd_n AS n, m.sd_q[2] AS median, m.sd_q[1] AS p25, m.sd_q[3] AS p75, sdh.l AS hist) AS v FROM m LEFT JOIN sdh ON sdh.model = m.model WHERE m.sd_n > 0), rm AS (SELECT model AS mm, k.1 AS mk, quantileExactWeightedInterpolated(0.5)(k.2, c) AS reach_mid FROM m ARRAY JOIN t_reaches.1 AS k, t_reaches.2 AS c GROUP BY mm, mk), rq AS (SELECT model AS qm, k.1 AS qk, sum(c) AS rn, quantilesExactWeightedInterpolated(0.25, 0.5, 0.75)(k.2, c) AS q, arraySort(groupArray([k.2, toInt64(c)])) AS v FROM m ARRAY JOIN t_ready.1 AS k, t_ready.2 AS c GROUP BY qm, qk), t AS (SELECT m.model AS model, action_id, n, hits, crits, t_targets[action_id] AS targets, measured, t_reach[action_id] AS reach, rm.reach_mid AS reach_mid, t_spread[action_id] AS spread, t_kb[action_id] AS kb, kb_uses, rq.rn AS ready_n, rq.q AS ready_q, rq.v AS ready_v, t_ready_coarse.2[indexOf(t_ready_coarse.1, action_id)] AS ready_coarse, move_distance(t_dist, action_id) AS distance, arrayMap(i -> [t_shadows.1[i].2, toInt64(t_shadows.1[i].3), toInt64(t_shadows.2[i])], arrayFilter(i -> t_shadows.1[i].1 = action_id, arrayEnumerate(t_shadows.1))) AS shadows, t_through.2[indexOf(t_through.1, action_id)] AS wiped, t_through.3[indexOf(t_through.1, action_id)] AS ignored FROM m ARRAY JOIN t_counts.1 AS action_id, t_counts.2 AS n, t_counts.3 AS hits, t_counts.4 AS crits, t_counts.5 AS measured, t_counts.6 AS kb_uses LEFT JOIN rm ON rm.mm = m.model AND rm.mk = action_id LEFT JOIN rq ON rq.qm = m.model AND rq.qk = action_id), c AS (SELECT model, action_id, n FROM m ARRAY JOIN c_casts.1 AS action_id, c_casts.2 AS n), ci AS (SELECT model, action_id, n FROM m ARRAY JOIN c_idle.1 AS action_id, c_idle.2 AS n), crq AS (SELECT model AS qm, k.1 AS qk, sum(c) AS rn, quantilesExactWeightedInterpolated(0.25, 0.5, 0.75)(k.2, c) AS q, arraySort(groupArray([k.2, toInt64(c)])) AS v FROM m ARRAY JOIN c_ready.1 AS k, c_ready.2 AS c GROUP BY qm, qk), sp AS (SELECT model, action_id, sum(n) AS n, sum(idle) AS idle FROM (SELECT model, action_id, n, toUInt64(0) AS idle FROM c UNION ALL SELECT model, action_id, n, n AS idle FROM ci) WHERE action_id > 0 GROUP BY model, action_id), s AS (SELECT model, spell_id, casts, resisted, immune, no_effect FROM m ARRAY JOIN s_results.1 AS spell_id, s_results.2 AS casts, s_results.3 AS resisted, s_results.4 AS immune, s_results.5 AS no_effect), hk AS (SELECT coalesce(model_id, -1) AS model, coalesce(level, -1) AS lv, countIf(coalesce(hp_regen, 0) > 0) AS regen, quantileExactInclusive(0.5)(hp_regen_rate) AS rate, countIf(coalesce(hp_healing, 0) > 0) AS healed FROM l WHERE hp_shaky IS NOT NULL AND (capture_id, fight_key) IN (SELECT k_owner, k_key FROM kc) GROUP BY ALL), hlo AS (SELECT model AS mm, k.1 AS mk, quantileExactWeightedInterpolated(0.5)(k.2, c) AS m_lo FROM m ARRAY JOIN h_level_lo.1 AS k, h_level_lo.2 AS c GROUP BY mm, mk), hhi AS (SELECT model AS mm, k.1 AS mk, quantileExactWeightedInterpolated(0.5)(k.2, c) AS m_hi FROM m ARRAY JOIN h_level_hi.1 AS k, h_level_hi.2 AS c GROUP BY mm, mk), hn AS (SELECT m.model AS model, lv, n, hlo.m_lo AS m_lo, hhi.m_hi AS m_hi FROM m ARRAY JOIN h_levels.1 AS lv, h_levels.2 AS n LEFT JOIN hlo ON hlo.mm = m.model AND hlo.mk = lv LEFT JOIN hhi ON hhi.mm = m.model AND hhi.mk = lv), hl AS (SELECT hn.model AS model, arrayMap(t -> t.2, arraySort(t -> t.1, groupArray(((hn.lv = -1, -hn.n, hn.lv), tuple(if(hn.lv = -1, NULL, hn.lv) AS level, hn.n AS n, hn.m_lo AS lo, hn.m_hi AS hi, hk.regen AS regen, hk.rate AS rate, hk.healed AS healed))))) AS l FROM hn LEFT JOIN hk ON hk.model = hn.model AND hk.lv = hn.lv GROUP BY hn.model), h AS (SELECT m.model AS model, tuple(m.h_n AS n, hl.l AS levels) AS v FROM m JOIN hl ON hl.model = m.model WHERE m.h_n > 0), ma AS (SELECT model, r_n AS n, r_off / r_n AS off_hand, r_kicks / r_n AS kicks FROM m WHERE r_n > 0), mh AS (SELECT g.model AS model, arrayMap(t -> t.2, arraySort(t -> t.1, groupArray((g.k, tuple(g.k AS k, coalesce(x.c, 0) AS n, wilson(coalesce(x.c, 0), g.n, 1.96) AS ci))))) AS l FROM (SELECT model, n, arrayJoin([1, 2, 3, 4]) AS k FROM ma) g LEFT JOIN (SELECT model, main_hand, c FROM m ARRAY JOIN r_main.1 AS main_hand, r_main.2 AS c) x ON x.model = g.model AND x.main_hand = g.k GROUP BY g.model), mz AS (SELECT model, arraySum(r_hit.2) AS hn, arraySum((k, c) -> if(k = 2, c, 0), r_hit.1, r_hit.2) AS h2, arraySum(r_miss.2) AS mn, arraySum((k, c) -> if(k = 2, c, 0), r_miss.1, r_miss.2) AS m2 FROM m), multi AS (SELECT ma.model AS model, tuple(ma.n AS rounds, ma.off_hand AS off_hand, ma.kicks AS kicks, mh.l AS main_hand, tuple(mz.hn AS hit_rounds, mz.h2 AS hit_doubles, wilson(mz.h2, mz.hn, 1.96) AS hit_ci) AS after_hit, tuple(mz.mn AS miss_rounds, mz.m2 AS miss_doubles, wilson(mz.m2, mz.mn, 1.96) AS miss_ci) AS after_miss) AS v FROM ma JOIN mh ON mh.model = ma.model LEFT JOIN mz ON mz.model = ma.model), acc AS (SELECT r.model AS model, coalesce(toString(nullIf(cp.character_id, 0)), r.capture_id) AS recorder_id, any(cp.character) AS recorder, sumMerge(r.passed) AS passed, sumMerge(r.missed) AS missed, sumMerge(r.hit_n) AS hits, coalesce(minArrayMerge(r.lmin), 0) AS lmin, coalesce(maxArrayMerge(r.lmax), 0) AS lmax, maxArrayMerge(r.corrected) AS corrected, maxArrayMerge(r.level_unknown) AS level_unknown, if(countArrayMerge(r.eva_seen) = sumMerge(r.swung) AND minArrayMerge(r.eva_min) = maxArrayMerge(r.eva_max), minArrayMerge(r.eva_min), NULL) AS eva, if(countArrayMerge(r.floor_seen) = sumMerge(r.swung), minArrayMerge(r.floor_min), NULL) AS eva_floor FROM r LEFT JOIN (SELECT capture_id, character, character_id FROM captures WHERE capture_id IN (SELECT capture_id FROM r)) cp ON cp.capture_id = r.capture_id GROUP BY model, recorder_id), ac AS (SELECT *, wilson(passed, passed + missed, 1.96) AS ci FROM acc WHERE passed + missed > 0), ap AS (SELECT *, acc_diff_lo(ci, lmax) AS diff_lo, acc_diff_hi(ci, lmin) AS diff_hi, diff_lo + coalesce(eva, eva_floor) AS acc_lo, diff_hi + eva AS acc_hi FROM ac), cm AS (SELECT model, sum(passed) AS passed, sum(missed) AS missed, sum(hits) AS hits, min(lmin) AS lmin, max(lmax) AS lmax, max(corrected) AS corrected, max(level_unknown) AS level_unknown, if(count() = 1, any(eva), NULL) AS eva, if(count() = 1, any(eva_floor), NULL) AS eva_floor, if(count() = 1, any(diff_lo), NULL) AS diff_lo, if(count() = 1, any(diff_hi), NULL) AS diff_hi, max(acc_lo) AS top_lo, min(acc_hi) AS top_hi, arrayMap(t -> t.2, arraySort(t -> t.1, groupArray(((-(passed + missed), recorder), tuple(recorder AS who, passed + missed AS swings, acc_lo AS acc_lo, acc_hi AS acc_hi))))) AS recorders FROM ap GROUP BY model), cc AS (SELECT *, wilson(passed, passed + missed, 1.96) AS ci, wilson(hits, hits + missed, 1.96) AS strict, top_lo IS NOT NULL AND top_hi IS NOT NULL AND top_lo > top_hi AS apart FROM cm), au AS (SELECT model, tuple(passed AS passed, missed AS missed, ci AS ci, hits AS hits, strict AS strict, acc_state(ci) AS state, diff_lo AS diff_lo, diff_hi AS diff_hi, corrected AS corrected, level_unknown AS level_unknown, lmin AS lmin, lmax AS lmax, eva AS eva, eva_floor AS eva_floor, if(NOT apart, top_lo, NULL) AS acc_lo, if(NOT apart, top_hi, NULL) AS acc_hi, recorders AS recorders) AS v FROM cc), tg AS (SELECT model, b, c FROM m ARRAY JOIN g_bins.1 AS b, g_bins.2 AS c), th AS (SELECT model, arrayMap(t -> t.2, arraySort(t -> t.1, groupArray((b, tuple(b AS b, n AS n))))) AS l FROM (SELECT model, b, n FROM m ARRAY JOIN g_hist.1 AS b, g_hist.2 AS n) GROUP BY model), tpd AS (SELECT tg.model AS model, tuple(sum(tg.c) AS n, argMax(tg.b, tg.c * 1000 - tg.b) AS mode, max(tg.c) AS at_mode, any(th.l) AS hist) AS v FROM tg LEFT JOIN th ON th.model = tg.model GROUP BY tg.model), sl AS (SELECT m.model AS model, mob_id, sl_lo[mob_id] AS lo, sl_hi[mob_id] AS hi, if(n > 0, sl_least[mob_id], NULL) AS least FROM m ARRAY JOIN sl_counts.1 AS mob_id, sl_counts.4 AS n), slots AS (SELECT model, arrayMap(t -> t.1, arraySort(t -> t.2, groupArray((tuple(mob_id AS id, lo AS lo, hi AS hi, least AS respawn), mob_id)))) AS l FROM sl GROUP BY model), dk AS (SELECT model, if(t = -1, NULL, t) AS th, kills FROM m ARRAY JOIN dr_kills.1 AS t, dr_kills.2 AS kills), di AS (SELECT model, if(key.1 = -1, NULL, key.1) AS th, key.2 AS item, n FROM m ARRAY JOIN dr_items.1 AS key, dr_items.2 AS n), rh AS (SELECT model, if(key.1 = -1, NULL, key.1) AS th, key.2 AS item, n AS held FROM m ARRAY JOIN dr_held.1 AS key, dr_held.2 AS n), rb AS (SELECT model, if(t = -1, NULL, t) AS th, n AS blind FROM m ARRAY JOIN dr_blind.1 AS t, dr_blind.2 AS n), ri AS (SELECT DISTINCT model, item FROM di), rj AS (SELECT dk.model AS model, dk.th AS th, dk.kills AS kills, ri.item AS item, coalesce(di.n, 0) AS n, toInt64(dk.kills) - if(ri.item IN (SELECT id FROM item_rare), toInt64(coalesce(rh.held, 0) + coalesce(rb.blind, 0)), 0) AS of FROM dk JOIN ri ON ri.model = dk.model LEFT JOIN di ON di.model = dk.model AND isNotDistinctFrom(di.th, dk.th) AND di.item = ri.item LEFT JOIN rh ON rh.model = dk.model AND isNotDistinctFrom(rh.th, dk.th) AND rh.item = ri.item LEFT JOIN rb ON rb.model = dk.model AND isNotDistinctFrom(rb.th, dk.th)), dt AS (SELECT dk.model AS model, dk.th AS th, any(dk.kills) AS kills, arrayMap(t -> t.2, arraySort(t -> t.1, groupArrayIf(((-j.n, j.item), tuple(j.item AS item, j.n AS n, j.of AS of, wilson(j.n, greatest(j.of, 1), 1.96) AS ci)), j.item IS NOT NULL))) AS items FROM dk LEFT JOIN rj j ON j.model = dk.model AND isNotDistinctFrom(j.th, dk.th) GROUP BY dk.model, dk.th), dl AS (SELECT model, arrayMap(t -> t.2, arraySort(t -> t.1, groupArray(((isNotNull(th), th), tuple(th AS th, kills AS kills, items AS items))))) AS l FROM dt GROUP BY model), sct AS (SELECT model, k.1 AS chain, k.2 AS spell, k.3 AS exposed, arrayMap(x -> [x.1, x.2], arraySort(x -> -x.1, groupArray((k.4, n)))) AS tiers FROM m ARRAY JOIN sc_t.1 AS k, sc_t.2 AS n GROUP BY model, chain, spell, exposed), scl AS (SELECT model, k.1 AS chain, k.2 AS spell, k.3 AS exposed, lo, sc_h.2[indexOf(sc_h.1, k)] AS hi FROM m ARRAY JOIN sc_l.1 AS k, sc_l.2 AS lo), scs AS (SELECT t.model AS model, arrayMap(x -> x.2, arraySort(x -> x.1, groupArray(((t.chain, t.exposed, NOT t.spell), tuple(t.chain AS chain, t.spell AS spell, t.exposed AS exposed, t.tiers AS tiers, l.lo AS lo, l.hi AS hi))))) AS l FROM sct t LEFT JOIN scl l ON l.model = t.model AND l.chain = t.chain AND l.spell = t.spell AND l.exposed = t.exposed GROUP BY t.model) SELECT toString(m.model) AS name, m.model AS model, {name:String} AS mob, (SELECT any(name) FROM zone_names WHERE id = {zone:Int64}) AS zone_name, m.n_fights AS fights, m.n_defeated AS defeated, m.n_captures AS captures, dy.v AS delay, sdy.v AS skill_delay, tpd.v AS tp_delay, multi.v AS multi, au.v AS accuracy, tl.l AS tp, cl.l AS casts, ss.l AS taken, h.v AS hp, slots.l AS slots, dl.l AS drops, scs.l AS skillchains, (SELECT groupArray(tuple(spells AS spells, casts AS casts, ratio AS ratio)) FROM fast_cast WHERE zone_id = {zone:Int64} AND mob_name = {name:String}) AS fast_cast FROM m LEFT JOIN dy ON dy.model = m.model LEFT JOIN sdy ON sdy.model = m.model LEFT JOIN tpd ON tpd.model = m.model LEFT JOIN multi ON multi.model = m.model LEFT JOIN au ON au.model = m.model LEFT JOIN (SELECT model, arrayMap(t -> t.2, arraySort(t -> t.1, groupArray(((-n, action_id), tuple(action_id AS id, n AS n, hits AS hits, crits AS crits, targets AS targets, measured AS measured, reach AS reach, reach_mid AS reach_mid, spread AS spread, kb AS kb, kb_uses AS kb_uses, ready_n AS ready_n, ready_q AS ready_q, ready_v AS ready_v, ready_coarse AS ready_coarse, shadows AS shadows, wiped AS wiped, ignored AS ignored, distance AS distance))))) AS l FROM t GROUP BY model) tl ON tl.model = m.model LEFT JOIN (SELECT sp.model AS model, arrayMap(t -> t.2, arraySort(t -> t.1, groupArray(((-sp.n, sp.action_id), tuple(sp.action_id AS id, sp.n AS n, sp.idle AS idle, crq.rn AS ready_n, crq.q AS ready_q, crq.v AS ready_v, m.c_recast.2[indexOf(m.c_recast.1, sp.action_id)] AS recast, m.c_recast_n.2[indexOf(m.c_recast_n.1, sp.action_id)] AS recast_n))))) AS l FROM sp JOIN m ON m.model = sp.model LEFT JOIN crq ON crq.qm = sp.model AND crq.qk = sp.action_id GROUP BY sp.model) cl ON cl.model = m.model LEFT JOIN (SELECT model, arrayMap(t -> t.2, arraySort(t -> t.1, groupArray(((-casts, spell_id), [spell_id, casts, resisted, immune, no_effect])))) AS l FROM s GROUP BY model) ss ON ss.model = m.model LEFT JOIN h ON h.model = m.model LEFT JOIN slots ON slots.model = m.model LEFT JOIN dl ON dl.model = m.model LEFT JOIN scs ON scs.model = m.model ORDER BY m.n_fights DESC, m.model
